from collections import Counter

# Score categories.
# Change the values as you see fit.
YACHT = "yacht"
ONES = "ones"
TWOS = "twos"
THREES = "threes"
FOURS = "fours"
FIVES = "fives"
SIXES = "sixes"
FULL_HOUSE = "full_house"
FOUR_OF_A_KIND = "four_of_a_kind"
LITTLE_STRAIGHT = "little_straight"
BIG_STRAIGHT = "big_straight"
CHOICE = "choice"


def score(dice, category):
    counts = Counter(dice)
    if category == YACHT:
        return 50 if len(counts) == 1 else 0

    if category == ONES:
        return counts[1] * 1
    if category == TWOS:
        return counts[2] * 2
    if category == THREES:
        return counts[3] * 3
    if category == FOURS:
        return counts[4] * 4
    if category == FIVES:
        return counts[5] * 5
    if category == SIXES:
        return counts[6] * 6

    if category == FULL_HOUSE:
        # Exactly two distinct faces with counts 2 and 3
        c = sorted(counts.values())
        return sum(dice) if c == [2, 3] else 0

    if category == FOUR_OF_A_KIND:
        # At least four of a kind: score is sum of the four dice (4 * face)
        for face, cnt in counts.items():
            if cnt >= 4:
                return face * 4
        return 0

    if category == LITTLE_STRAIGHT:
        return 30 if set(dice) == {1, 2, 3, 4, 5} else 0

    if category == BIG_STRAIGHT:
        return 30 if set(dice) == {2, 3, 4, 5, 6} else 0

    if category == CHOICE:
        return sum(dice)

    # Unknown category
    return 0
